import { test, expect } from '@playwright/test';

test('sorting by name descending', async ({ page }) => {
  await page.goto('/products');
  await page.getByLabel('Category').selectOption('Fruit');
  const name = page.getByRole('button', { name: 'Name' });
  await name.click();
  await name.click();
  await expect(page.getByRole('columnheader', { name: 'Name' })).toHaveAttribute('aria-sort', 'descending');
  // 1.64: locator.within() — the first cell of every row = the Name column
  const nameColumn = page.getByRole('cell').first().within(page.getByRole('row'));
  await expect(nameColumn).toHaveText(['Date', 'Cherry', 'Banana', 'Apple']);
});

test('aria snapshot of the login form', async ({ page }) => {
  await page.goto('/login');
  await expect(page.getByRole('main')).toMatchAriaSnapshot(`
    - heading "Sign in" [level=1]
    - textbox "Email"
    - textbox "Password"
    - paragraph:
      - button "Sign in"
  `);
  // Templates match a subsequence of children at each level: the button sits inside a <p>,
  // so it must be nested under '- paragraph:'.
});
